contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 outputAmount) public payable {
        // Need a valid pool; initialize it first.  Use ETH base token and a known NFT.
        c.initialize(address(0), address(this), 1e18, 1e18, 0, 100, bytes32(0), false, false);
        require(outputAmount > 0 && outputAmount < c.virtualNftReserves(), "outputAmount out of range");
        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);
        uint256 rawInput = (outputAmount * uint256(c.virtualBaseTokenReserves()) + (c.virtualNftReserves() - outputAmount) - 1) / (c.virtualNftReserves() - outputAmount);
        assert(netInputAmount == rawInput + feeAmount + protocolFeeAmount);
    }

    receive() external payable {}
}

