contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 depositAmount, uint256 buyAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount + buyAmount, "insufficient balance");
        require(depositAmount <= address(this).balance - buyAmount, "insufficient balance 2");

        address baseToken = c.baseToken();
        require(baseToken == address(0), "rule only for ETH pools");

        uint256 beforeBalance = address(c).balance;

        c.deposit{value: depositAmount}(new uint256[](0), depositAmount);
        uint256 afterDeposit = address(c).balance;

        uint256 buyNet;
        {
            uint256[] memory ids = new uint256[](0);
            uint256[] memory weights = new uint256[](0);
            C.MerkleMultiProof memory proof = C.MerkleMultiProof(new bytes32[](0), new bool[](0));
            (buyNet, , ) = c.buy{value: buyAmount}(ids, weights, proof);
        }
        uint256 afterBuy = address(c).balance;

        uint256 withdrawAmountSafe = withdrawAmount % (afterBuy + 1);
        c.withdraw(baseToken, new uint256[](0), address(0), withdrawAmountSafe);
        uint256 finalBalance = address(c).balance;

        assert(finalBalance == afterDeposit - buyNet - withdrawAmountSafe);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint256 depositAmount, uint256 buyAmount, uint256 withdrawAmount) public payable {
        require(c.baseToken() == address(0), "rule only for ETH pools");
        require(address(this).balance >= depositAmount + buyAmount, "insufficient balance");

        uint256 initialBalance = address(c).balance;

        c.deposit{value: depositAmount}(new uint256[](0), depositAmount);

        uint256[] memory emptyIds = new uint256[](0);
        uint256[] memory emptyWeights = new uint256[](0);
        C.MerkleMultiProof memory emptyProof = C.MerkleMultiProof(new bytes32[](0), new bool[](0));
        (uint256 netInputAmount, , ) = c.buy{value: buyAmount}(emptyIds, emptyWeights, emptyProof);

        uint256 safeWithdraw = withdrawAmount % (initialBalance + depositAmount + 1);
        c.withdraw(address(0), new uint256[](0), address(0), safeWithdraw);

        uint256 finalBalance = address(c).balance;

        assert(finalBalance == initialBalance + depositAmount - netInputAmount - safeWithdraw);
    }
}
